-- Refresh school dataset 23/11/2026 (schools: 249, verified scholarships: 190, BEA state living costs: 51, reference fees: True, field_evidence: 7755).
SET LOCAL standard_conforming_strings = on;
SET LOCAL lock_timeout = '10s';

-- 1. Ensure all 249 schools exist (preserve existing is_ivy / is_active if already present)
ON CONFLICT (code) DO NOTHING;

-- 2. Overlay verified 23/11 values onto universities and undergraduate university_offerings
CREATE TEMP TABLE _refresh_school_231126 (code text PRIMARY KEY, university_data jsonb NOT NULL, offering_data jsonb NOT NULL) ON COMMIT DROP;

WITH incoming AS (
    SELECT t.id, jsonb_populate_record(NULL::app.universities, to_jsonb(t) || s.university_data) AS row_data
    FROM _refresh_school_231126 s
    JOIN app.universities t ON t.code = s.code
)
UPDATE app.universities target
SET name = (incoming.row_data).name,
    city = (incoming.row_data).city,
    state = (incoming.row_data).state,
    website = (incoming.row_data).website,
    control = (incoming.row_data).control,
    acceptance_rate = (incoming.row_data).acceptance_rate,
    international_student_count = (incoming.row_data).international_student_count,
    is_ivy = (incoming.row_data).is_ivy,
    updated_at = CURRENT_TIMESTAMP
FROM incoming
WHERE target.id = incoming.id
  AND ROW(target.name, target.city, target.state, target.website, target.control, target.acceptance_rate, target.international_student_count, target.is_ivy) IS DISTINCT FROM ROW((incoming.row_data).name, (incoming.row_data).city, (incoming.row_data).state, (incoming.row_data).website, (incoming.row_data).control, (incoming.row_data).acceptance_rate, (incoming.row_data).international_student_count, (incoming.row_data).is_ivy);

SELECT gen_random_uuid(), u.id, 'undergraduate', CURRENT_TIMESTAMP
FROM _refresh_school_231126 s
JOIN app.universities u ON u.code = s.code
ON CONFLICT (university_id, study_level) DO NOTHING;

WITH incoming AS (
    SELECT t.id, jsonb_populate_record(NULL::app.university_offerings, to_jsonb(t) || s.offering_data || CASE WHEN s.offering_data ? 'deadlines_json' THEN jsonb_build_object('deadlines_json', COALESCE(NULLIF(t.deadlines_json, 'null'::jsonb), '{}'::jsonb) || (s.offering_data->'deadlines_json')) ELSE '{}'::jsonb END) AS row_data
    FROM _refresh_school_231126 s
    JOIN app.universities u ON u.code = s.code
    JOIN app.university_offerings t ON t.university_id = u.id AND t.study_level = 'undergraduate'
)
UPDATE app.university_offerings target
SET academic_year = (incoming.row_data).academic_year,
    tuition_usd = (incoming.row_data).tuition_usd,
    fees_usd = (incoming.row_data).fees_usd,
    living_usd = (incoming.row_data).living_usd,
    other_expenses_usd = (incoming.row_data).other_expenses_usd,
    health_insurance_usd = (incoming.row_data).health_insurance_usd,
    application_fee_usd = (incoming.row_data).application_fee_usd,
    act_policy = (incoming.row_data).act_policy,
    act_submit_pct = (incoming.row_data).act_submit_pct,
    tuition_in_state_usd = (incoming.row_data).tuition_in_state_usd,
    min_gpa4 = (incoming.row_data).min_gpa4,
    min_ielts = (incoming.row_data).min_ielts,
    min_toefl = (incoming.row_data).min_toefl,
    min_duolingo = (incoming.row_data).min_duolingo,
    avg_gpa4 = (incoming.row_data).avg_gpa4,
    avg_gpa_weighted = (incoming.row_data).avg_gpa_weighted,
    gpa_scale_type = (incoming.row_data).gpa_scale_type,
    sat25 = (incoming.row_data).sat25,
    sat75 = (incoming.row_data).sat75,
    act25 = (incoming.row_data).act25,
    act75 = (incoming.row_data).act75,
    sat_policy = (incoming.row_data).sat_policy,
    sat_submit_pct = (incoming.row_data).sat_submit_pct,
    gpa_submit_pct = (incoming.row_data).gpa_submit_pct,
    gpa_pct_4_0 = (incoming.row_data).gpa_pct_4_0,
    gpa_pct_375_399 = (incoming.row_data).gpa_pct_375_399,
    gpa_pct_350_374 = (incoming.row_data).gpa_pct_350_374,
    gpa_pct_325_349 = (incoming.row_data).gpa_pct_325_349,
    gpa_pct_300_324 = (incoming.row_data).gpa_pct_300_324,
    gpa_pct_250_299 = (incoming.row_data).gpa_pct_250_299,
    gpa_pct_below_250 = (incoming.row_data).gpa_pct_below_250,
    c7_gpa_importance = (incoming.row_data).c7_gpa_importance,
    c7_test_importance = (incoming.row_data).c7_test_importance,
    c7_ec_importance = (incoming.row_data).c7_ec_importance,
    applicants_total = (incoming.row_data).applicants_total,
    admitted_total = (incoming.row_data).admitted_total,
    intl_applicants = (incoming.row_data).intl_applicants,
    intl_admitted = (incoming.row_data).intl_admitted,
    intl_acceptance_rate = (incoming.row_data).intl_acceptance_rate,
    intl_aid_policy = (incoming.row_data).intl_aid_policy,
    intl_aid_avg_usd = (incoming.row_data).intl_aid_avg_usd,
    intl_aid_recipients = (incoming.row_data).intl_aid_recipients,
    retention_rate_1yr = (incoming.row_data).retention_rate_1yr,
    grad_rate_6yr = (incoming.row_data).grad_rate_6yr,
    fy_on_campus_pct = (incoming.row_data).fy_on_campus_pct,
    ug_on_campus_pct = (incoming.row_data).ug_on_campus_pct,
    housing_types = (incoming.row_data).housing_types,
    intl_housing = (incoming.row_data).intl_housing,
    housing_only_usd = (incoming.row_data).housing_only_usd,
    housing_deposit_usd = (incoming.row_data).housing_deposit_usd,
    student_faculty_ratio = (incoming.row_data).student_faculty_ratio,
    activities = (incoming.row_data).activities,
    campus_setting = (incoming.row_data).campus_setting,
    deadlines_json = (incoming.row_data).deadlines_json,
    source_url = (incoming.row_data).source_url,
    retrieved_at = (incoming.row_data).retrieved_at,
    source_reliability = (incoming.row_data).source_reliability,
    updated_at = CURRENT_TIMESTAMP
FROM incoming
WHERE target.id = incoming.id
  AND ROW(target.academic_year, target.tuition_usd, target.fees_usd, target.living_usd, target.other_expenses_usd, target.health_insurance_usd, target.application_fee_usd, target.act_policy, target.act_submit_pct, target.tuition_in_state_usd, target.min_gpa4, target.min_ielts, target.min_toefl, target.min_duolingo, target.avg_gpa4, target.avg_gpa_weighted, target.gpa_scale_type, target.sat25, target.sat75, target.act25, target.act75, target.sat_policy, target.sat_submit_pct, target.gpa_submit_pct, target.gpa_pct_4_0, target.gpa_pct_375_399, target.gpa_pct_350_374, target.gpa_pct_325_349, target.gpa_pct_300_324, target.gpa_pct_250_299, target.gpa_pct_below_250, target.c7_gpa_importance, target.c7_test_importance, target.c7_ec_importance, target.applicants_total, target.admitted_total, target.intl_applicants, target.intl_admitted, target.intl_acceptance_rate, target.intl_aid_policy, target.intl_aid_avg_usd, target.intl_aid_recipients, target.retention_rate_1yr, target.grad_rate_6yr, target.fy_on_campus_pct, target.ug_on_campus_pct, target.housing_types, target.intl_housing, target.housing_only_usd, target.housing_deposit_usd, target.student_faculty_ratio, target.activities, target.campus_setting, target.deadlines_json, target.source_url, target.retrieved_at, target.source_reliability) IS DISTINCT FROM ROW((incoming.row_data).academic_year, (incoming.row_data).tuition_usd, (incoming.row_data).fees_usd, (incoming.row_data).living_usd, (incoming.row_data).other_expenses_usd, (incoming.row_data).health_insurance_usd, (incoming.row_data).application_fee_usd, (incoming.row_data).act_policy, (incoming.row_data).act_submit_pct, (incoming.row_data).tuition_in_state_usd, (incoming.row_data).min_gpa4, (incoming.row_data).min_ielts, (incoming.row_data).min_toefl, (incoming.row_data).min_duolingo, (incoming.row_data).avg_gpa4, (incoming.row_data).avg_gpa_weighted, (incoming.row_data).gpa_scale_type, (incoming.row_data).sat25, (incoming.row_data).sat75, (incoming.row_data).act25, (incoming.row_data).act75, (incoming.row_data).sat_policy, (incoming.row_data).sat_submit_pct, (incoming.row_data).gpa_submit_pct, (incoming.row_data).gpa_pct_4_0, (incoming.row_data).gpa_pct_375_399, (incoming.row_data).gpa_pct_350_374, (incoming.row_data).gpa_pct_325_349, (incoming.row_data).gpa_pct_300_324, (incoming.row_data).gpa_pct_250_299, (incoming.row_data).gpa_pct_below_250, (incoming.row_data).c7_gpa_importance, (incoming.row_data).c7_test_importance, (incoming.row_data).c7_ec_importance, (incoming.row_data).applicants_total, (incoming.row_data).admitted_total, (incoming.row_data).intl_applicants, (incoming.row_data).intl_admitted, (incoming.row_data).intl_acceptance_rate, (incoming.row_data).intl_aid_policy, (incoming.row_data).intl_aid_avg_usd, (incoming.row_data).intl_aid_recipients, (incoming.row_data).retention_rate_1yr, (incoming.row_data).grad_rate_6yr, (incoming.row_data).fy_on_campus_pct, (incoming.row_data).ug_on_campus_pct, (incoming.row_data).housing_types, (incoming.row_data).intl_housing, (incoming.row_data).housing_only_usd, (incoming.row_data).housing_deposit_usd, (incoming.row_data).student_faculty_ratio, (incoming.row_data).activities, (incoming.row_data).campus_setting, (incoming.row_data).deadlines_json, (incoming.row_data).source_url, (incoming.row_data).retrieved_at, (incoming.row_data).source_reliability);

-- 3. Upsert CIP 2020 majors (keep curated name_vi/aliases/is_popular) & verified CDS J1 offering-major links
ON CONFLICT (name) DO UPDATE SET cip_code = EXCLUDED.cip_code, updated_at = CURRENT_TIMESTAMP WHERE app.majors.cip_code IS DISTINCT FROM EXCLUDED.cip_code;

CREATE TEMP TABLE _refresh_majors_231126 (code text NOT NULL, major_name text NOT NULL, is_stem boolean NOT NULL) ON COMMIT DROP;
SELECT o.id, m.id, r.is_stem, TRUE
FROM _refresh_majors_231126 r
JOIN app.universities u ON u.code = r.code
JOIN app.university_offerings o ON o.university_id = u.id AND o.study_level = 'undergraduate'
JOIN app.majors m ON m.name = r.major_name
ON CONFLICT (university_offering_id, major_id) DO UPDATE SET is_stem = EXCLUDED.is_stem, is_verified = TRUE;

-- 4. Upsert 190 verified scholarships (deterministic UUID v5 by scholarship_id)
ON CONFLICT (id) DO UPDATE SET university_id = EXCLUDED.university_id, name = EXCLUDED.name, provider = EXCLUDED.provider, study_level = EXCLUDED.study_level, amount_usd = EXCLUDED.amount_usd, coverage_type = EXCLUDED.coverage_type, min_gpa4 = EXCLUDED.min_gpa4, min_ielts = EXCLUDED.min_ielts, deadline = EXCLUDED.deadline, eligibility_notes = EXCLUDED.eligibility_notes, source_url = EXCLUDED.source_url, retrieved_at = EXCLUDED.retrieved_at, source_reliability = EXCLUDED.source_reliability, is_active = EXCLUDED.is_active, kind = EXCLUDED.kind, amount_type = EXCLUDED.amount_type, amount_min_usd = EXCLUDED.amount_min_usd, amount_max_usd = EXCLUDED.amount_max_usd, duration_years = EXCLUDED.duration_years, renewable = EXCLUDED.renewable, renewal_criteria = EXCLUDED.renewal_criteria, intl_eligible = EXCLUDED.intl_eligible, vn_eligible = EXCLUDED.vn_eligible, need_based = EXCLUDED.need_based, merit_based = EXCLUDED.merit_based, min_sat = EXCLUDED.min_sat, min_act = EXCLUDED.min_act, min_toefl = EXCLUDED.min_toefl, major_restriction = EXCLUDED.major_restriction, application_method = EXCLUDED.application_method, apply_url = EXCLUDED.apply_url, updated_at = CURRENT_TIMESTAMP;

-- 5. Upsert 51 BEA SARPP 2024 state living cost indices (UC-28)
ON CONFLICT (state_code, year) DO UPDATE SET index_all_items = EXCLUDED.index_all_items, index_housing_rents = EXCLUDED.index_housing_rents, index_goods = EXCLUDED.index_goods, index_other_services = EXCLUDED.index_other_services, source_url = EXCLUDED.source_url, retrieved_at = EXCLUDED.retrieved_at, updated_at = CURRENT_TIMESTAMP;

-- 6. Upsert F-1 visa MRV ($185) and SEVIS I-901 ($350) reference fees (UC-26)
ON CONFLICT (key) DO UPDATE SET value_json = EXCLUDED.value_json, description = EXCLUDED.description, updated_at = CURRENT_TIMESTAMP;

-- 7. Insert verified 23/11 field_evidence rows (newest CreatedAt takes precedence on detail page)
CREATE TEMP TABLE _refresh_evidence_231126 (id uuid PRIMARY KEY, code text NOT NULL, field_name text NOT NULL, field_value text, source_url text, source_section text, extracted_quote text NOT NULL, verified_by text NOT NULL, status text NOT NULL) ON COMMIT DROP;
SELECT e.id, u.id, e.field_name, e.field_value, e.source_url, e.source_section, e.extracted_quote, e.verified_by, e.status, CURRENT_TIMESTAMP
FROM _refresh_evidence_231126 e
JOIN app.universities u ON u.code = e.code
ON CONFLICT (id) DO NOTHING;

DROP TABLE _refresh_evidence_231126;
DROP TABLE _refresh_majors_231126;
DROP TABLE _refresh_school_231126;
